description:
Implement the core data structures in src/collection.rs.

Public types:

  pub struct PartEntry {
      pub part_number: u32,         // 1-based; 0 = TOC
      pub body_bytes: Vec<u8>,      // raw bytes of this part's UU body (caller extracted from MIME)
      pub subject: Option<String>,  // original Subject header value, stored for diagnostics
  }

  pub struct PartCollection {
      parts: BTreeMap<u32, PartEntry>,  // private; keyed by part_number
      total: Option<u32>,               // declared total, if known
  }

  impl PartCollection {
      pub fn new() -> Self
      pub fn with_total(total: u32) -> Self
      pub fn add(&mut self, entry: PartEntry) -> Result<(), MultiUuError>
          // Returns DuplicatePart if part_number already present
          // Updates self.total if entry.part_number > current total estimate
      pub fn total(&self) -> Option<u32>
          // Returns declared total or inferred max part number seen
      pub fn present_parts(&self) -> impl Iterator<Item = u32> + '_
      pub fn missing_parts(&self) -> Vec<u32>
          // Returns sorted list of 1..=total that are absent
          // Returns empty vec if total is None (cannot determine)
      pub fn is_complete(&self) -> bool
          // true iff total is known and missing_parts() is empty
      pub fn toc_part(&self) -> Option<&PartEntry>
          // Returns entry with part_number == 0, if present
      pub fn len(&self) -> usize
      pub fn is_empty(&self) -> bool
  }

All public types: Debug, Clone, Serialize (feature-gated), Deserialize (feature-gated).

Tests:
  - Add parts out of order; verify present_parts() is sorted
  - Detect gap: add parts 1,2,4 with total=4 -> missing=[3]
  - Duplicate part returns DuplicatePart error
  - is_complete() true when all parts present
  - is_complete() false when total unknown
  - toc_part() returns part 0 if present
  - with_total() constrains missing_parts() correctly
